def slide_right(grid):
    h,w=len(grid),len(grid[0])
    # connected components (4-conn, nonzero)
    seen=[[False]*w for _ in range(h)]; shapes=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j] and not seen[i][j]:
                cells=[]; q=deque([(i,j)]); seen[i][j]=True
                while q:
                    r,c=q.popleft(); cells.append((r,c,grid[r][c]))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<h and 0<=nc<w and grid[nr][nc] and not seen[nr][nc]:
                            seen[nr][nc]=True; q.append((nr,nc))
                shapes.append(cells)
    # iterative simultaneous shift
    while True:
        occ=[[False]*w for _ in range(h)]
        for cells in shapes:
            for r,c,v in cells: occ[r][c]=True
        moved=False; newpos=[]
        for cells in shapes:
            ok=True
            for r,c,v in cells:
                nc=c+1
                if nc>=w or (occ[r][nc] and not any(rr==r and cc==nc for rr,cc,_ in cells)):
                    ok=False; break
            if ok:
                moved=True
                newpos.append([(r,c+1,v) for r,c,v in cells])
            else:
                newpos.append(cells)
        shapes=newpos
        if not moved: break
    out=[[0]*w for _ in range(h)]
    for cells in shapes:
        for r,c,v in cells: out[r][c]=v
    return out

